package school.chacademia.wildlife;
import org.junit.jupiter.api.Test;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.configuration.file.YamlConfiguration;
import org.joml.Vector3f;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class WildlifeFeedbackTest {
 @Test void rarityAttemptProbabilityIsSeparateFromSelectionWeight(){var s=WildSpawner.Settings.parse(null,new ArrayList<>());assertEquals(Map.of("1",1d,"2",.5,"3",.08,"boss",.01),s.rarityChance());assertEquals(.2,s.similarWeight());assertEquals(24,s.similarRadius());var y=new YamlConfiguration();y.set("rarity-attempt-chance.3",2);y.set("rarity-attempt-chance.boss",-1);var warnings=new ArrayList<String>();var configured=WildSpawner.Settings.parse(y,warnings);assertEquals(1,configured.rarityChance().get("3"));assertEquals(0,configured.rarityChance().get("boss"));assertEquals(2,warnings.size());}
 @Test void familyGroupingAndExplicitOverride(){assertEquals("golem",Habitat.family("golem_arcane"));assertEquals("golem",Habitat.family("golem_royal"));assertEquals("bear",Habitat.family("baby_polar_bear"));assertEquals("bear",Habitat.family("bear_black"));assertEquals("mf_warden",Habitat.family("mf_warden_mage"));assertEquals("ncr",Habitat.family("ncr_warrior_skeleton"));var y=new YamlConfiguration();y.set("biomes",List.of("minecraft:plains"));y.set("group-min",1);y.set("group-max",1);y.set("cap",2);y.set("min-y",-64);y.set("max-y",320);y.set("family","custom");assertEquals("custom",Habitat.parse("bear_black",y,new ArrayList<>()).family());}
 @Test void nearbyFamilyReducesOnlyRelatedSpeciesWeight()throws Exception{var plugin=mock(WildlifePlugin.class);var spawner=new WildSpawner(plugin);var f=WildSpawner.class.getDeclaredField("settings");f.setAccessible(true);f.set(spawner,WildSpawner.Settings.parse(null,new ArrayList<>()));var y=new YamlConfiguration();y.set("biomes",List.of("minecraft:plains"));y.set("group-min",1);y.set("group-max",1);y.set("cap",2);y.set("min-y",-64);y.set("max-y",320);var h=Habitat.parse("bear_black",y,new ArrayList<>());var method=WildSpawner.class.getDeclaredMethod("weight",Habitat.class,Set.class);method.setAccessible(true);assertEquals(4.5,(double)method.invoke(spawner,h,Set.of("golem")),1e-6);assertEquals(.9,(double)method.invoke(spawner,h,Set.of("bear")),1e-6);}
 @Test void actualModelEngineVectorScaleChecksVisualAndHitboxAxes(){assertTrue(MobScale.matches(new Vector3f(1.35f),1.35));assertFalse(MobScale.matches(new Vector3f(1.35f,1,1.35f),1.35));assertFalse(MobScale.matches(null,1.35));}
 @Test void combatDefaultsAndBounds(){var s=WildCombat.Settings.parse(null);assertTrue(s.enabled());assertEquals(8,s.farDistance());assertEquals(96,s.chaseMax());assertEquals(4000,s.skillCooldownMs());assertEquals(10000,s.outOfCombatMs());assertEquals(.05,s.regenFraction());var y=new YamlConfiguration();y.set("chase-max",999);y.set("skill-cooldown",0);y.set("out-of-combat-seconds",0);y.set("regen-percent",200);var b=WildCombat.Settings.parse(y);assertEquals(128,b.chaseMax());assertEquals(500,b.skillCooldownMs());assertEquals(1000,b.outOfCombatMs());assertEquals(1,b.regenFraction());}
 @Test void creativeParticipatesAndSpectatorDoesNot()throws Exception{for(GameMode mode:List.of(GameMode.CREATIVE,GameMode.SPECTATOR)){var plugin=mock(WildlifePlugin.class);var world=mock(World.class);var player=mock(Player.class);when(plugin.spawnWorlds()).thenReturn(Set.of("world"));when(plugin.playerMinDistance()).thenReturn(24d);when(plugin.playerMaxDistance()).thenReturn(80d);when(world.getPlayers()).thenReturn(List.of(player));when(player.getGameMode()).thenReturn(mode);when(player.getEntityId()).thenReturn(1);when(player.getWorld()).thenReturn(world);when(player.getLocation()).thenReturn(new Location(world,0,64,0));var s=new WildSpawner(plugin);var f=WildSpawner.class.getDeclaredField("settings");f.setAccessible(true);f.set(s,WildSpawner.Settings.parse(null,new ArrayList<>()));var tick=WildSpawner.class.getDeclaredMethod("tick");tick.setAccessible(true);try(var b=mockStatic(Bukkit.class)){b.when(()->Bukkit.getWorld("world")).thenReturn(world);tick.invoke(s);}verify(world,mode==GameMode.CREATIVE?times(3):never()).isChunkLoaded(anyInt(),anyInt());verify(world,never()).getChunkAt(anyInt(),anyInt());}}
}
